for (const [a,b] of [[6,8],[10,14]]) text((await tools.exec_command({cmd:"cat "+p.slice(a,b).map(p=>"'"+p+"'").join(" "),max_output_tokens:11000})).output);
text((await tools.exec_command({cmd:"sed -n '1,195p' .agents/skills/json-render/SKILL.md",max_output_tokens:5000})).output);

// @exec: {"max_output_tokens": 16000}
const p=load("mandatoryPreloadPaths");
const r=await Promise.allSettled([
tools.exec_command({cmd:"cat "+p.slice(14,17).join(" "),max_output_tokens:11000}),
tools.exec_command({cmd:"cat "+p.slice(17,21).join(" "),max_output_tokens:9000}),
]);
for(let i=0;i<r.length;i++)text({batch:i,result:r[i]});

// @exec: {"max_output_tokens": 12500}
